            let tracked ptraw = permraw.join(padding);
            let mj = m2;
            m2.tracked_insert(i, (ptraw, block_token));
            assert(mj.dom().contains(i) == false);
            assert(m2.dom() =~= mj.dom().insert(i));
            assert(m2.dom().len() == mj.dom().len() + 1);
            assert(m2.len() == len);
